// hidden test helpers: {count, mean, variance}
std::vector<double> report(const RunningStats& s) { return {double(s.count()), s.mean(), s.variance()}; }
std::vector<double> stats_of(const std::vector<double>& xs) {
    RunningStats s;
    for (double x : xs) s.add(x);
    return report(s);
}
std::vector<double> merged(const std::vector<double>& a, const std::vector<double>& b) {
    RunningStats p, q;
    for (double x : a) p.add(x);
    for (double x : b) q.add(x);
    p.merge(q);
    return report(p);
}

